const int LED = 9;
const float FULL_MA = 13.6;   // the current while the pin is on: (5 - 2) / 220 A
const float STEPS_MA[] = {13.6, 6.8, 3.4};

void setup() {
  Serial.begin(9600);
  pinMode(LED, OUTPUT);
}

void loop() {
  for (int i = 0; i < 3; i++) {
    int duty = round(STEPS_MA[i] / FULL_MA * 255);   // the share of each cycle the pin is on, 0-255
    analogWrite(LED, duty);
    Serial.print(STEPS_MA[i], 1);
    Serial.print(" mA average, duty ");
    Serial.println(duty);
    delay(1000);
  }
}

