// Three currents with digitalWrite(): it only does full or nothing
const int LED = 9;   // pin 9 -> 220 ohm -> LED -> GND

void setup() {
  Serial.begin(9600);
  pinMode(LED, OUTPUT);
}

void loop() {
  digitalWrite(LED, HIGH);   // 13.6 mA: (5 - 2) / 220
  Serial.println("13.6 mA");
  delay(1000);
  digitalWrite(LED, HIGH);   // half the current? digitalWrite has only HIGH and LOW
  Serial.println("6.8 mA");
  delay(1000);
  digitalWrite(LED, HIGH);
  Serial.println("3.4 mA");
  delay(1000);
}

